import{_ as e,a as r,c as a,ac as n}from"./chunks/framework.BSuaGltH.js";const c=JSON.parse('{"title":"六十四卦详读一：乾坤至师比 · 07 师：动众必须承担责任至读后比较与自测","description":"对读《周易》与《周易正义》，逐爻理解乾、坤、屯、蒙、需、讼、师、比八卦。","frontmatter":{"title":"六十四卦详读一：乾坤至师比 · 07 师：动众必须承担责任至读后比较与自测","description":"对读《周易》与《周易正义》，逐爻理解乾、坤、屯、蒙、需、讼、师、比八卦。","splitFrom":"life/personal/yijing/hexagrams-01-08.md","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"基础学习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"六十四卦详读一：乾坤至师比","summary":"对读《周易》与《周易正义》，逐爻理解乾、坤、屯、蒙、需、讼、师、比八卦。","status":"active","related":[{"title":"第七号嫌疑人","link":"/life/personal/reading-games/suspect-number-seven","kind":"生活记录","scope":"general","audience":"general"},{"title":"佳能入门","link":"/life/personal/photography/canon","kind":"生活记录","scope":"general","audience":"general"},{"title":"《十翼》逐篇阅读：七种十篇怎样帮助理解《周易》","link":"/life/personal/yijing/ten-wings","kind":"基础学习","scope":"general","audience":"general"},{"title":"《算法》书目与主题导读（版本待确认）","link":"/life/personal/books/computing/algorithms","kind":"书籍导读","scope":"general","audience":"general"},{"title":"《周易》是怎样的一部书：经、传、注与成书问题","link":"/life/personal/yijing/text-history","kind":"基础学习","scope":"general","audience":"general"}],"prev":{"text":"六十四卦详读一：乾坤至师比 · 04 蒙：如何问、如何教、如何养成至06 讼：争执的边界与开端","link":"/life/personal/yijing/hexagrams-01-08-part-02"},"next":{"text":"六十四卦详读二：小畜履泰否至同人大有谦豫","link":"/life/personal/yijing/hexagrams-09-16"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"六十四卦详读一：乾坤至师比 · 04 蒙：如何问、如何教、如何养成至06 讼：争执的边界与开端","link":"/life/personal/yijing/hexagrams-01-08-part-02"},"next":{"text":"六十四卦详读二：小畜履泰否至同人大有谦豫","link":"/life/personal/yijing/hexagrams-09-16"}},"headers":[],"relativePath":"life/personal/yijing/hexagrams-01-08-part-03.md","filePath":"life/personal/yijing/hexagrams-01-08-part-03.md"}'),i={name:"life/personal/yijing/hexagrams-01-08-part-03.md"};function o(s,t,l,d,p,g){return r(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="六十四卦详读一-乾坤至师比-·-07-师-动众必须承担责任至读后比较与自测" tabindex="-1">六十四卦详读一：乾坤至师比 · 07 师：动众必须承担责任至读后比较与自测 <a class="header-anchor" href="#六十四卦详读一-乾坤至师比-·-07-师-动众必须承担责任至读后比较与自测" aria-label="Permalink to &quot;六十四卦详读一：乾坤至师比 · 07 师：动众必须承担责任至读后比较与自测&quot;">​</a></h1><p><a href="/life/personal/yijing/hexagrams-01-08">返回分篇目录</a></p><p>这一组从天地、生长与启蒙，进入等待、争讼、组织与亲比。卦序提供阅读线索，并不是每个人都必须按顺序经历的人生阶段。先读卦辞与《大象》，再把六爻自下而上读一遍，留意同一卦里为什么既有“吉”，又有“凶”。</p><p>本文实际对读维基文库《周易》各卦及王弼注、孔颖达疏《周易正义》对应篇。引文保留繁体及“无”等古字，标点为便于阅读所加；网上录文的异体、断句与古注解释并不完全一致，下文必要时说明。表格左栏是古籍原文，右栏及“读法”是本篇白话概括，不是古人原句。古代占筮判断属于其历史语境，不能当作科学预测；君臣、婚姻与性别秩序也不直接作为现代规范。</p><h2 id="gua-07" tabindex="-1">07 师：动众必须承担责任 <a class="header-anchor" href="#gua-07" aria-label="Permalink to &quot;07 师：动众必须承担责任 {#gua-07}&quot;">​</a></h2><p><strong>卦符：䷆　上卦：坤 ☷（地、顺）　下卦：坎 ☵（水、险）。</strong></p><p><strong>卦辞原文</strong>：師：貞，丈人吉，无咎。</p><p><strong>白话概括</strong>：“师”在此主要是军旅与众人，不是教师。“丈人”指庄重有担当的主事者，并非今天的岳父称谓。《正义》强调兴役动众若不能承担后果便有罪责，故全卦谈纪律、将帅、退驻与战后分封。它反映古代军事政治，不宜轻率挪作鼓励竞争或征服的口号。</p><table tabindex="0"><thead><tr><th>爻位与原文</th><th>白话概括</th></tr></thead><tbody><tr><td>初六：師出以律，否臧，凶。</td><td>出师须有纪律与法度；失序会带来凶险。“否臧”的断解有异，核心不可丢掉“失律”的警告。</td></tr><tr><td>九二：在師中吉，无咎；王三錫命。</td><td>居众中而得适当指挥，获得授权。古注以刚中与相应解释，不能把赏赐次数当预测。</td></tr><tr><td>六三：師或輿尸，凶。</td><td>军队可能载尸而归，直指失败的代价；“舆尸”亦有主事众多等古注解释，不能抹去战争伤亡的语境。</td></tr><tr><td>六四：師左次，无咎。</td><td>军队退驻或驻于合适位置，没有咎责。战术退却不自动等于怯懦。</td></tr><tr><td>六五：田有禽，利執言，无咎。長子帥師，弟子輿尸，貞凶。</td><td>以田禽为侵害之象，讲应对与用人。“执言”有异解；对主将适任性的要求，比血缘称谓本身更值得注意。</td></tr><tr><td>上六：大君有命，開國承家，小人勿用。</td><td>战后封赏并建立秩序，不能把善于争战直接等同于适合治理。功劳与任职资格是两回事。</td></tr></tbody></table><p><strong>《大象》原文</strong>：“地中有水，師；君子以容民畜衆。”</p><p><strong>解释</strong>：水蕴于地中，众人有赖平时的容养。师的基础并非一时命令，而是民众的生活与社会积累；“畜众”中的畜是养聚，不应理解为把人当物品控制。</p><p><strong>整体读法与误区</strong>：初六讲出发纪律，上六讲结束之后如何用人，说明行动的前后都属于责任范围。六四的无咎又提醒，不行动、暂退有时比逞强更负责。现代组织可以有限借鉴授权与适任原则，但战争的伤害和古代等级不能被淡化成轻松的团队管理比喻。</p><p><strong>细读线索</strong>：师只有九二一个阳爻，却位在下卦之中，古注因而把它视作主将；六五居尊位而与之相应，区分了任命者和执行者。这种结构提醒人注意授权、实际能力与责任是否相称。六三与六五重复舆尸，把错误用人的代价加重；上六再谈小人勿用，则把战时之功与平时治理分开。阅读军事象辞时，须连同受动员者的负担看，不能只看主将的荣耀。</p><p><strong>古籍对读</strong>：<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%B8%AB" target="_blank" rel="noopener noreferrer">《周易·师》</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%AD%A3%E7%BE%A9/02%E5%B8%AB" target="_blank" rel="noopener noreferrer">《周易正义·上经需传卷二·师》</a>。</p><h2 id="gua-08" tabindex="-1">08 比：亲近谁，以及怎样相处 <a class="header-anchor" href="#gua-08" aria-label="Permalink to &quot;08 比：亲近谁，以及怎样相处 {#gua-08}&quot;">​</a></h2><p><strong>卦符：䷇　上卦：坎 ☵（水）　下卦：坤 ☷（地）。比在此重亲比、相辅。</strong></p><p><strong>卦辞原文</strong>：比：吉。原筮，元永貞，无咎。不寧方來，後夫凶。</p><p><strong>白话概括</strong>：相互亲近可带来安定，但必须追究关系的根本，能否长久而正。《正义》明确区分正当相辅与结党逐利，不把“大家聚在一起”自动视为善。“后夫凶”涉及归附迟滞与关系失时，不能直接推成迟到者应被排斥；“原筮”也保留着占筮文本的背景。</p><table tabindex="0"><thead><tr><th>爻位与原文</th><th>白话概括</th></tr></thead><tbody><tr><td>初六：有孚，比之，无咎。有孚盈缶，終來有它，吉。</td><td>亲比从诚实而非华饰开始，像朴素瓦缶中装得充实。“有它”可理解为另有相助，不必臆测神秘赠礼。</td></tr><tr><td>六二：比之自內，貞吉。</td><td>亲近出于内在认可，并守正，不以失去自身原则换取接纳。</td></tr><tr><td>六三：比之匪人。</td><td>所亲近的对象不适当。经文没有另写吉凶，但《小象》直接指出伤害，提示择友与择所归的重要。</td></tr><tr><td>六四：外比之，貞吉。</td><td>向外亲近合适者，同样须守正。与六二相对，内外位置不同，善恶不由“内外”两字决定。</td></tr><tr><td>九五：顯比。王用三驅，失前禽，邑人不誡，吉。</td><td>公开而合宜地亲比，以田猎不尽取为象。古注强调舍逆取顺，关系不靠穷追强留；三驱制度有不同解释。</td></tr><tr><td>上六：比之无首，凶。</td><td>亲比失去恰当开端或主导，难有善终。这里“无首”的情境与乾用九不同，不能只按同一词面判断。</td></tr></tbody></table><p><strong>《大象》原文</strong>：“地上有水，比；先王以建萬國，親諸侯。”</p><p><strong>解释</strong>：水与地相亲，借古代邦国关系说明建立联结、维持相辅。它并不意味着所有人必须归入同一个中心；古注的政治结构须作为历史知识阅读。</p><p><strong>整体读法与误区</strong>：比既谈被接纳，也谈选择和边界。六三提醒对象可能不当，九五提示不以强制求齐，上六提醒关系需要可靠的起点。与<a href="/life/personal/yijing/hexagrams-01-08-part-03#gua-07">师卦</a>并读，师偏向动员中的纪律，比偏向日常的亲辅；有组织不等于有信任，有亲近也不等于一切正当。</p><p><strong>细读线索</strong>：比只有九五一阳，诸阴围绕它相应，是古注讨论亲比中心的结构基础。可是初六的盈缶、六二的自内都强调关系参与者本身的诚实与完整，并不只要求服从中心。六三用极短的匪人提醒对象可能有误。九五田猎失前禽尤其能纠正占有式理解：有些离去不必追尽，有些联结不该强求。由此看比，亲近的质量比人数和排他程度更重要。</p><p><strong>古籍对读</strong>：<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%AF%94" target="_blank" rel="noopener noreferrer">《周易·比》</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%AD%A3%E7%BE%A9/02%E6%AF%94" target="_blank" rel="noopener noreferrer">《周易正义·上经需传卷二·比》</a>。</p><h2 id="读后比较与自测" tabindex="-1">读后比较与自测 <a class="header-anchor" href="#读后比较与自测" aria-label="Permalink to &quot;读后比较与自测 {#读后比较与自测}&quot;">​</a></h2><ol><li>乾的“自强”为什么需要与“潜龙”“亢龙”一起理解？坤的“顺”又由什么限制？</li><li>屯六三主张舍，六四却许往；需初九与九三也不同。改变判断的是哪一项条件？</li><li>蒙为什么既讲包容，也讲纠正？如何区分解释古代刑罚与认可现代体罚？</li><li>师与比都涉及众人，为什么一个强调纪律、另一个强调选择与亲辅？</li><li>乾用九“无首”吉，比上六“无首”凶，说明逐字套公式会遗漏什么？</li></ol><p>继续阅读：<a href="/life/personal/yijing/hexagrams-09-16">第 09—16 卦：小畜至豫</a>。返回 <a href="/life/personal/yijing/overview">易经专题导读</a>。</p>',27)])])}const f=e(i,[["render",o]]);export{c as __pageData,f as default};
